/**
 * Assembles the folder that goes to the production server. Run on a dev
 * machine (needs npm); the server only ever receives the finished bundle.
 *
 *   node scripts/make-deploy-bundle.mjs            (builds, then assembles)
 *   node scripts/make-deploy-bundle.mjs --skip-build
 *
 * Output: deploy/chatisa-app/  containing
 *   server.js + node_modules + .next   (Next standalone build, native
 *                                       better-sqlite3 for Windows included)
 *   public/                            (WASM runtimes, workers, brand)
 *   assets/                            (Miami brand assets read at runtime)
 *   chatisa-server.mjs                 (launcher: env + child + TLS on 443)
 *   chatisa.bat                        (what Task Scheduler runs)
 *   chatisa.env.example                (fill in and rename to chatisa.env)
 *   INSTALL.txt                        (step-by-step server instructions)
 */
import { cp, mkdir, rm, writeFile, readFile, stat, readdir } from "node:fs/promises";
import { existsSync } from "node:fs";
import { join, dirname, relative, sep } from "node:path";
import { fileURLToPath } from "node:url";
import { spawnSync } from "node:child_process";

const web = join(dirname(fileURLToPath(import.meta.url)), "..");
const bundle = join(web, "deploy", "chatisa-app");
const skipBuild = process.argv.includes("--skip-build");

/**
 * Stamps the footer's "Updated" date, which must happen BEFORE next build.
 *
 * The date has to be frozen at bundle time: a visitor next month should still
 * see the date this bundle was made. Writing it as a source literal that the
 * build compiles in is what guarantees that. The alternatives do not: the
 * footer is a server component, so `new Date()` re-evaluates per request, and
 * `process.env` would be read on a server that never had the variable set.
 *
 * Written with LOCAL date parts and an explicit month list, so the stamp is the
 * builder's calendar day regardless of timezone or machine locale.
 */
const MONTHS = [
  "January", "February", "March", "April", "May", "June",
  "July", "August", "September", "October", "November", "December",
];
const buildInfoPath = join(web, "lib", "config", "build-info.ts");

function renderBuildInfo(label) {
  return `/**
 * GENERATED by scripts/make-deploy-bundle.mjs. Do not edit by hand; the next
 * bundle run overwrites it.
 *
 * The date shown in the site footer. It is written here as a string LITERAL
 * before \`next build\` runs, which is what freezes it: the literal is compiled
 * into the output, so every visitor sees the date this bundle was made rather
 * than the date they happened to open the app. The footer is a server
 * component, so \`new Date()\` would re-evaluate on every request and
 * \`process.env\` would be read at request time on a server that never had the
 * variable set. A literal has neither problem.
 *
 * Between bundle runs this holds the date of the last bundle, which is the
 * honest answer to "when was the running app last updated".
 */
export const BUILD_DATE = ${JSON.stringify(label)};
`;
}

let updatedLabel;
if (skipBuild) {
  // Nothing is recompiled, so whatever date is already inside .next is the
  // truth. Re-stamping the source here would make the manifest and INSTALL
  // notes disagree with the footer the server actually renders.
  const current = await readFile(buildInfoPath, "utf8").catch(() => "");
  updatedLabel =
    /BUILD_DATE = "([^"]+)"/.exec(current)?.[1] ?? "unknown";
  console.log(`--skip-build: keeping the already-compiled footer date (${updatedLabel}).`);
} else {
  const now = new Date();
  updatedLabel = `${MONTHS[now.getMonth()]} ${now.getDate()}, ${now.getFullYear()}`;
  await writeFile(buildInfoPath, renderBuildInfo(updatedLabel));
  console.log(`Stamped footer date: ${updatedLabel}`);
}

if (!skipBuild) {
  console.log("Building (next build)...");
  const result = spawnSync("npm", ["run", "build"], {
    cwd: web,
    stdio: "inherit",
    shell: true,
  });
  if (result.status !== 0) {
    console.error("Build failed; bundle not assembled.");
    process.exit(1);
  }
}

const standalone = join(web, ".next", "standalone");
if (!existsSync(join(standalone, "server.js"))) {
  console.error(".next/standalone/server.js missing. Run without --skip-build.");
  process.exit(1);
}

console.log("Assembling deploy/chatisa-app ...");
await rm(bundle, { recursive: true, force: true });
await mkdir(bundle, { recursive: true });
// dereference is LOAD-BEARING: Turbopack's standalone output aliases
// externalized packages (.next/node_modules/pino-<hash>, better-sqlite3-<hash>)
// as Windows JUNCTIONS pointing at ABSOLUTE paths on the build machine. A
// plain copy ships the junction, which resolves here and nowhere else (the
// production failure of 2026-07-25). Dereferencing materializes real files.
const copyOpts = { recursive: true, dereference: true };

/**
 * Directories that must NEVER be copied out of .next/standalone (2026-07-26).
 *
 * Next's standalone output mirrors the project directory, and it had picked up
 * two things that do not belong in a shipped bundle:
 *
 *   data/    the DEVELOPMENT SQLite database. The copy found on disk held 3 user
 *            rows (email addresses), 150 usage events, 126 exam document page
 *            excerpts, and 2 tailored resumes. None of that should leave the
 *            build machine, and production reads CHATISA_DATA_DIR anyway, so the
 *            file was pure leakage with no purpose.
 *   deploy/  the PREVIOUS bundle. Each build embedded the last one, so the tree
 *            nested three deep and deploy/ had grown to 612 MB.
 *
 * Excluded by name rather than by .gitignore or a manifest, because this is about
 * what the ZIP contains and nothing else enforces that.
 */
const NEVER_BUNDLE = ["data", "deploy"];
const standaloneFilter = (src) => {
  const rel = relative(standalone, src);
  if (rel === "") return true;
  const top = rel.split(sep)[0];
  return !NEVER_BUNDLE.includes(top);
};
await cp(standalone, bundle, { ...copyOpts, filter: standaloneFilter });
await cp(join(web, ".next", "static"), join(bundle, ".next", "static"), copyOpts);
await cp(join(web, "public"), join(bundle, "public"), copyOpts);
await cp(join(web, "assets"), join(bundle, "assets"), copyOpts);
await cp(
  join(web, "scripts", "chatisa-server.mjs"),
  join(bundle, "chatisa-server.mjs"),
);
// Diagnoses "speech is broken" from ON the server: DNS -> TCP -> TLS -> HTTPS
// -> a real token mint, with a control host, so a firewall block, a TLS
// inspection appliance, and a bad credential each produce a distinct verdict.
await cp(
  join(web, "scripts", "speech-doctor.mjs"),
  join(bundle, "speech-doctor.mjs"),
);

// Prove portability before zipping: no symlink or junction may survive
// anywhere in the bundle, and the aliased packages must be real files.
console.log("Verifying the bundle is self-contained ...");
const { readdirSync, lstatSync, readFileSync, existsSync: exists } = await import("node:fs");
const leftoverLinks = [];
function scanLinks(dir) {
  for (const entry of readdirSync(dir, { withFileTypes: true })) {
    const p = join(dir, entry.name);
    if (lstatSync(p).isSymbolicLink()) leftoverLinks.push(p);
    else if (entry.isDirectory()) scanLinks(p);
  }
}
scanLinks(bundle);
if (leftoverLinks.length > 0) {
  console.error("FATAL: the bundle still contains links (not portable):");
  for (const p of leftoverLinks) console.error("  " + p);
  process.exit(1);
}
const aliasDir = join(bundle, ".next", "node_modules");
if (exists(aliasDir)) {
  for (const name of readdirSync(aliasDir)) {
    if (!exists(join(aliasDir, name, "package.json"))) {
      console.error(`FATAL: aliased package ${name} has no package.json (broken copy).`);
      process.exit(1);
    }
  }
}
console.log("  self-contained: no links, alias packages materialized");

/**
 * No development data anywhere in the bundle (2026-07-26).
 *
 * A filter on one cp() is not enough on its own: the leak arrived because a
 * SOURCE directory quietly gained contents nobody expected, and the next such
 * surprise will come from somewhere else. This checks the finished artifact, so it
 * catches any path that produces the same outcome.
 *
 * Fatal rather than a warning. Shipping a student's email address or an excerpt of
 * their uploaded notes is not something to note in a log and continue past.
 */
const forbiddenPaths = [];
function scanForbidden(dir) {
  for (const entry of readdirSync(dir, { withFileTypes: true })) {
    const p = join(dir, entry.name);
    const rel = relative(bundle, p);
    // A .db anywhere, and any nested copy of the bundle directory itself.
    if (entry.isFile() && /\.db(-wal|-shm)?$/i.test(entry.name)) {
      forbiddenPaths.push(`${rel}  (database)`);
      continue;
    }
    if (entry.isDirectory()) {
      if (entry.name === "deploy") {
        forbiddenPaths.push(`${rel}  (a nested copy of the bundle)`);
        continue; // do not descend; one report is enough
      }
      scanForbidden(p);
    }
  }
}
scanForbidden(bundle);
if (forbiddenPaths.length > 0) {
  console.error(
    "FATAL: the bundle contains development data that must not be shipped:",
  );
  for (const p of forbiddenPaths) console.error("  " + p);
  console.error(
    "  The database holds user emails and document excerpts; a nested deploy/ folder",
  );
  console.error(
    "  is a previous bundle. Both come from .next/standalone; see NEVER_BUNDLE above.",
  );
  process.exit(1);
}
console.log("  no development data: no .db files, no nested deploy/");

// Worker child processes (workers/*.mjs) are spawned at runtime, so Next's
// dependency tracing never sees their imports; unpdf was missing from the
// first production deploy (2026-07-25) and PDF features failed only there.
// Copy every bare import of every worker with its full production dependency
// tree (optional deps only when installed locally, e.g. the win32 canvas).
const workersDir = join(bundle, "workers");
if (exists(workersDir)) {
  // Walk the workers' import graphs: bare specifiers become package copies,
  // RELATIVE specifiers (../lib/exam/pdf-core.mjs, also invisible to Next's
  // tracing; second self-test catch of 2026-07-25) are copied from the source
  // tree at the same relative path and recursed into.
  const needed = new Set();
  const relSeen = new Set();
  const { relative: relPath, resolve: resolvePath } = await import("node:path");
  async function walkModule(webFile) {
    const rel = relPath(web, webFile);
    if (relSeen.has(rel)) return;
    relSeen.add(rel);
    const bundleFile = join(bundle, rel);
    if (!exists(bundleFile)) {
      await mkdir(dirname(bundleFile), { recursive: true });
      await cp(webFile, bundleFile);
      console.log(`  worker relative import copied: ${rel}`);
    }
    const src = readFileSync(webFile, "utf8");
    for (const m of src.matchAll(/(?:from\s+|import\()\s*["']([^"']+)["']/g)) {
      const spec = m[1];
      if (spec.startsWith("node:")) continue;
      if (spec.startsWith(".")) {
        await walkModule(resolvePath(dirname(webFile), spec));
      } else {
        needed.add(
          spec.startsWith("@") ? spec.split("/").slice(0, 2).join("/") : spec.split("/")[0],
        );
      }
    }
  }
  for (const f of readdirSync(workersDir).filter((f) => f.endsWith(".mjs"))) {
    await walkModule(join(web, "workers", f));
  }
  const copied = [];
  async function copyPkg(name, optional) {
    const destPkg = join(bundle, "node_modules", ...name.split("/"));
    if (exists(destPkg)) return;
    const srcPkg = join(web, "node_modules", ...name.split("/"));
    if (!exists(srcPkg)) {
      if (optional) return; // platform-specific optionals for other OSes
      console.error(`FATAL: worker dependency "${name}" is not installed locally.`);
      process.exit(1);
    }
    await cp(srcPkg, destPkg, copyOpts);
    copied.push(name);
    const pj = JSON.parse(readFileSync(join(srcPkg, "package.json"), "utf8"));
    for (const dep of Object.keys(pj.dependencies ?? {})) await copyPkg(dep, false);
    for (const dep of Object.keys(pj.optionalDependencies ?? {})) await copyPkg(dep, true);
  }
  for (const pkg of needed) await copyPkg(pkg, false);
  for (const pkg of needed) {
    if (!exists(join(bundle, "node_modules", ...pkg.split("/"), "package.json"))) {
      console.error(`FATAL: worker dependency "${pkg}" missing after copy.`);
      process.exit(1);
    }
  }
  console.log(
    `  worker deps (${[...needed].join(", ")}): ${copied.length > 0 ? `copied ${copied.length} packages` : "already present"}`,
  );
}

// Self-test: BOOT the assembled bundle and require the deep health check
// (real PDF worker parse, db write with read-back, brand assets) to pass
// before this bundle may ship. Runs before the ABI swap below, since the
// swapped driver targets the SERVER's Node, not this machine's.
console.log("Self-test: booting the assembled bundle ...");
{
  const selftestData = join(web, ".cache", "selftest-data");
  await mkdir(selftestData, { recursive: true });
  await writeFile(
    join(bundle, "chatisa.env"),
    [
      "CHATISA_HTTP_ONLY=1",
      "CHATISA_HTTPS_PORT=3299",
      "AUTH_SECRET=bundle-selftest-secret-0123456789",
      "AUTH_URL=http://localhost:3299",
      "AUTH_GOOGLE_ID=selftest-placeholder",
      "AUTH_GOOGLE_SECRET=selftest-placeholder",
      `CHATISA_DATA_DIR=${selftestData}`,
      "",
    ].join("\n"),
  );
  const { spawn } = await import("node:child_process");
  const proc = spawn(process.execPath, ["chatisa-server.mjs"], {
    cwd: bundle,
    stdio: "ignore",
  });
  let health = null;
  for (let i = 0; i < 30 && !health?.checks?.deep; i++) {
    await new Promise((r) => setTimeout(r, 2000));
    try {
      const res = await fetch("http://127.0.0.1:3299/api/health?deep=1");
      health = await res.json();
    } catch {
      /* still booting */
    }
  }
  spawnSync("taskkill", ["/PID", String(proc.pid), "/F", "/T"]);
  await rm(join(bundle, "chatisa.env"), { force: true });
  await rm(join(bundle, "chatisa.log"), { force: true });
  /**
   * Deep checks that may legitimately report something other than "ok" HERE,
   * with the exact value that is acceptable.
   *
   * `speech` joined the deep block on 2026-07-26 and immediately failed this
   * self-test, because the boot above deliberately supplies no DEEPGRAM_TOKEN:
   * "not-configured" is the correct answer in this environment, not a fault.
   *
   * Narrow on purpose. Only these keys, and only these values: a `speech`
   * of "broken: ..." still fails the bundle, which is the state that
   * matters (a credential that is present and refused). Everything else
   * stays strict.
   *
   * `scout` joined the deep block on 2026-07-28 and failed this self-test
   * the same way speech did on 2026-07-26: the boot above uses a fresh
   * data directory and no harvest keys, so "no harvest yet" is the correct
   * answer in this environment. Any other non-ok scout value (a failed
   * query, a stale-feed report from a corrupted table) still fails.
   */
  const OPTIONAL_DEEP = {
    speech: /^not-configured\b/,
    scout: /^no harvest yet$/,
  };

  const deep = health?.checks?.deep;
  const bad = deep
    ? Object.entries(deep).filter(
        ([key, value]) => value !== "ok" && !OPTIONAL_DEEP[key]?.test(value),
      )
    : null;
  if (!deep || bad.length > 0) {
    console.error("FATAL: bundle self-test failed; this bundle must not ship.");
    console.error("  deep health: " + JSON.stringify(deep ?? health));
    process.exit(1);
  }
  const notes = Object.entries(deep)
    .filter(([, v]) => v !== "ok")
    .map(([k, v]) => `${k} ${v.split(":")[0]}`);
  console.log(
    `  self-test PASSED: ${Object.keys(deep).join(", ")}` +
      (notes.length ? ` (acceptable here: ${notes.join(", ")})` : " all ok"),
  );
}

// Native-binary targeting. better-sqlite3 compiles per Node ABI; the binary
// npm built here matches THIS machine's Node, not the server's (found
// 2026-07-25: dev Node 26/ABI 147 vs server Node 24 LTS/ABI 137 =
// ERR_DLOPEN_FAILED). The bundle therefore ships the OFFICIAL prebuilt
// binary for the TARGET ABI (default 137 = Node 24 LTS; override with
// --node-abi=<abi>), and a manifest the launcher checks so a mismatch is a
// plain sentence, not a DLL error. sharp needs no swap (Node-API, ABI-stable).
const ABI_TO_NODE = { 108: "18", 115: "20", 127: "22", 131: "23", 137: "24", 147: "26" };
const abiArg = process.argv.find((a) => a.startsWith("--node-abi="));
const targetAbi = abiArg ? abiArg.split("=")[1] : "137";
const bs3Version = JSON.parse(
  await (await import("node:fs/promises")).readFile(
    join(web, "node_modules", "better-sqlite3", "package.json"),
    "utf8",
  ),
).version;
if (targetAbi !== process.versions.modules) {
  console.log(
    `Fetching better-sqlite3 v${bs3Version} prebuilt for Node ABI ${targetAbi} (Node ${ABI_TO_NODE[targetAbi] ?? "?"})...`,
  );
  const cacheDir = join(web, ".cache");
  await mkdir(cacheDir, { recursive: true });
  const tarball = join(cacheDir, `better-sqlite3-v${bs3Version}-node-v${targetAbi}-win32-x64.tar.gz`);
  if (!existsSync(tarball)) {
    const url = `https://github.com/WiseLibs/better-sqlite3/releases/download/v${bs3Version}/better-sqlite3-v${bs3Version}-node-v${targetAbi}-win32-x64.tar.gz`;
    const res = await fetch(url);
    if (!res.ok) {
      console.error(`FATAL: no official prebuild at ${url} (HTTP ${res.status}).`);
      process.exit(1);
    }
    await writeFile(tarball, Buffer.from(await res.arrayBuffer()));
  }
  const extractDir = join(cacheDir, `bs3-${targetAbi}`);
  await rm(extractDir, { recursive: true, force: true });
  await mkdir(extractDir, { recursive: true });
  // Relative paths + cwd: bsdtar misreads absolute Windows paths ("C:" looks
  // like a remote host to it).
  const untar = spawnSync(
    "tar",
    ["-x", "-z", "-f", `better-sqlite3-v${bs3Version}-node-v${targetAbi}-win32-x64.tar.gz`, "-C", `bs3-${targetAbi}`],
    { cwd: cacheDir },
  );
  if (untar.status !== 0) {
    console.error("FATAL: could not extract the prebuild tarball.");
    process.exit(1);
  }
  const prebuilt = join(extractDir, "build", "Release", "better_sqlite3.node");
  const targets = [
    join(bundle, "node_modules", "better-sqlite3", "build", "Release", "better_sqlite3.node"),
  ];
  for (const name of readdirSync(aliasDir)) {
    if (name.startsWith("better-sqlite3-")) {
      targets.push(join(aliasDir, name, "build", "Release", "better_sqlite3.node"));
    }
  }
  for (const t of targets.filter((t) => exists(dirname(t)))) {
    await cp(prebuilt, t);
    console.log(`  swapped: ${t.slice(bundle.length + 1)}`);
  }
}
await writeFile(
  join(bundle, "chatisa-manifest.json"),
  JSON.stringify(
    {
      builtAt: new Date().toISOString(),
      // The same string the footer renders, so "what does the site say it was
      // updated" is answerable from the bundle without reading compiled chunks.
      footerDate: updatedLabel,
      nodeAbi: targetAbi,
      nodeMajor: ABI_TO_NODE[targetAbi] ?? null,
    },
    null,
    2,
  ),
);
console.log(`  bundle targets Node ${ABI_TO_NODE[targetAbi] ?? "?"} (ABI ${targetAbi})`);

// The launcher must run from EITHER of two locations, because a Task Scheduler
// action the operator cannot edit may point at a fixed path one level ABOVE the
// app folder (the real constraint on the Miami server, 2026-07-25). So it finds
// chatisa-server.mjs rather than assuming it sits beside the bat. The server
// itself resolves chatisa.env, chatisa.log, and server.js from its OWN
// directory and spawns Next with cwd set there, so once the path is found
// nothing else depends on where the bat lives.
await writeFile(
  join(bundle, "chatisa.bat"),
  [
    "@echo off",
    "rem ChatISA web app. Started by Windows Task Scheduler; the loop brings",
    "rem the server back if the whole process ever exits. The launcher writes",
    "rem everything to this window AND to chatisa.log itself.",
    "rem",
    "rem This file works from EITHER location:",
    "rem   inside the app folder:      ...\\chat_isa\\chatisa-app\\chatisa.bat",
    "rem   or one level above it:      ...\\chat_isa\\chatisa.bat",
    "rem The second exists for a Task Scheduler action whose path cannot be",
    "rem changed. chatisa.env and chatisa.log always stay INSIDE the app folder,",
    "rem beside chatisa-server.mjs, wherever this bat happens to sit.",
    "setlocal",
    'set "APP=%~dp0"',
    'if not exist "%APP%chatisa-server.mjs" set "APP=%~dp0chatisa-app\\"',
    'if not exist "%APP%chatisa-server.mjs" goto nofiles',
    'cd /d "%APP%"',
    ":loop",
    "node chatisa-server.mjs",
    "rem Absolute path on purpose: a stray timeout.exe earlier on PATH makes the",
    "rem wait fail and turns this into a hot restart loop (seen while testing).",
    '"%SystemRoot%\\System32\\timeout.exe" /t 5 /nobreak >nul',
    "goto loop",
    "",
    ":nofiles",
    "rem Do not enter the restart loop: without the app there is nothing to",
    "rem restart, and a silent spin would hide the real problem. Task Scheduler",
    "rem shows the non-zero exit, and the note below survives in a file because",
    "rem this failure happens before the server can open chatisa.log.",
    "echo [chatisa] chatisa-server.mjs was not found. ChatISA did NOT start.",
    "echo [chatisa] Looked beside this file:  %~dp0",
    "echo [chatisa] and in the app folder:    %~dp0chatisa-app\\",
    "echo [chatisa] Fix: keep chatisa.bat either INSIDE the extracted",
    "echo [chatisa] chatisa-app folder, or directly beside that folder.",
    '>>"%~dp0chatisa-launcher-error.log" echo %DATE% %TIME% chatisa-server.mjs not found from %~dp0',
    "exit /b 1",
    "",
  ].join("\r\n"),
);

await writeFile(
  join(bundle, "chatisa.env.example"),
  `# ChatISA server configuration. RENAME THIS FILE to chatisa.env and fill in
# every value marked REQUIRED. Lines starting with # are ignored.

# --- Site identity (REQUIRED) ------------------------------------------------
AUTH_URL=https://chatisa.fsb.miamioh.edu
# Any long random string; generate one with: node -e "console.log(crypto.randomBytes(32).toString('hex'))"
AUTH_SECRET=

# --- Google sign-in (REQUIRED; from console.cloud.google.com credentials) ----
# The OAuth client must list this redirect URI:
#   https://chatisa.fsb.miamioh.edu/api/auth/callback/google
AUTH_GOOGLE_ID=
AUTH_GOOGLE_SECRET=

# --- Model providers (REQUIRED for the modules to answer) --------------------
OPENAI_API_KEY=
ANTHROPIC_API_KEY=
GOOGLE_API_KEY=
HF_TOKEN=

# --- Speech (Interview Mentor voice) -----------------------------------------
DEEPGRAM_TOKEN=

# --- Ask Anything literature search ------------------------------------------
# Semantic Scholar's keyless pool is shared across every anonymous caller and
# answers 429 to nearly every request, so WITHOUT this key students see
# "Unavailable this time: Semantic Scholar." on essentially every search.
# Free academic key: https://www.semanticscholar.org/product/api#api-key-form
SEMANTIC_SCHOLAR_API_KEY=
# A contact address puts us in OpenAlex's faster pool. Use a role address, not
# a personal one; it is sent with every OpenAlex request.
OPENALEX_MAILTO=

# --- Job Scout weekly job feed -----------------------------------------------
# Without RAPIDAPI_KEY the Active Jobs DB source is skipped; without the USAJobs pair
# the federal track is skipped. Both absent = the feed stays empty and the
# module says so to students. USAJOBS_EMAIL is the registered account email,
# sent as the User-Agent per data.usajobs.gov terms.
RAPIDAPI_KEY=
USAJOBS_API_KEY=
USAJOBS_EMAIL=
# Comma-separated emails allowed to trigger a manual harvest via
# POST /api/scout/refresh (progress lands in the scout_runs table).
CHATISA_SCOUT_ADMINS=
# Per-run tagging cost ceiling in USD (default 10 when unset).
CHATISA_SCOUT_MAX_RUN_USD=

# --- GitHub publishing: Portfolio Builder and Job Scout (optional) -----------
# A GitHub OAuth App (github.com > Settings > Developer settings > OAuth Apps;
# an OAuth App, NOT a "GitHub App"). Authorization callback URL to register:
#   https://chatisa.fsb.miamioh.edu/api/scout/github/callback
# The callback URL sent to GitHub is built from AUTH_URL (not the incoming
# request), so AUTH_URL must be the public https origin.
# The server uses this pair ONLY to exchange the OAuth code for a token; the
# token lives in the student's browser and pushes go straight to GitHub.
# Scope requested: public_repo (cannot touch private repositories).
# Leave unset to hide the Connect, Push, and Publish buttons; the Portfolio
# Builder then has no destination, since GitHub is the only one.
GITHUB_OAUTH_CLIENT_ID=
GITHUB_OAUTH_CLIENT_SECRET=

# --- Data (REQUIRED): folder for the usage database; BACK THIS FOLDER UP -----
CHATISA_DATA_DIR=C:\\chatisa-data

# --- Guest invite links (optional; see docs/operations.md to mint) -----------
CHATISA_GUEST_PASS_HASHES=
CHATISA_GUEST_EXPIRES=

# --- TLS files (defaults are the paths the old Streamlit command used) -------
CHATISA_SSL_CERT=C:\\Users\\webapp\\.conda\\chat_isa\\ssl\\chatisa.pem
CHATISA_SSL_KEY=C:\\Users\\webapp\\.conda\\chat_isa\\ssl\\chatisapriv.key

# NEVER set on the server: AUTH_TEST_MODE, CHATISA_MOCK_LLM, CHATISA_MOCK_GITHUB,
# CHATISA_PROXY_ALLOW_LOCAL. They are test-only and refused in production.
`,
);

await writeFile(
  join(bundle, "INSTALL.txt"),
  `CHATISA SERVER INSTALL (Windows)
=================================
The server needs ONE program installed: Node.js. No npm, no Python, no R,
no Conda. Students' R and Python run inside their own browsers.

FIRST-TIME SETUP
----------------
1. Install Node.js version 24 (the LTS release; this bundle is built for it):
   - Download the Windows Installer (.msi, 64-bit) from https://nodejs.org
   - Next, Next, Finish. Then open a NEW Command Prompt and type:
       node --version
     You should see v24.x. If "not recognized", reboot once. The version
     matters: this bundle ships a compiled database module built for Node 24,
     and an older Node refuses to load it.

2. Stop the old Streamlit app (close its window / end its scheduled task).
   Keep the ssl folder: the new app uses the SAME certificate files.

3. Copy the archive (chatisa-app.zip) onto the server and extract it there
   WITH 7-ZIP, into the parent folder, for example:
       put chatisa-app.zip in   C:\\Users\\webapp\\.conda\\chat_isa\\
       right-click > 7-Zip > "Extract Here"
       which gives  C:\\Users\\webapp\\.conda\\chat_isa\\chatisa-app\\
   Use "Extract Here", not "Extract to chatisa-app\\": the archive already
   contains the chatisa-app folder, so the second choice nests it twice
   (chatisa-app\\chatisa-app\\) and step 6b then cannot find the app.

   Use 7-Zip, not Windows' built-in "Extract All". Despite the .zip name this
   archive is an uncompressed tar (the build machine's tar writes tar
   regardless of the extension). 7-Zip reads it by content and is fine with
   that; Explorer goes by the extension and refuses it. From a Command Prompt
   in the parent folder,  tar -xf chatisa-app.zip  also works.

   IMPORTANT: transfer the archive, not the raw folder. Dragging the folder
   over Remote Desktop can silently drop files; the server checks for damage
   at startup and will refuse to run an incomplete copy.

4. In the copied folder, make the settings file:
   - Copy chatisa.env.example, rename the copy to  chatisa.env
   - Open chatisa.env in Notepad and fill in every REQUIRED value.
   - Create the data folder named in CHATISA_DATA_DIR (default C:\\chatisa-data)
     and include it in your backups: it holds the usage database.

5. Test it once by double-clicking  chatisa.bat  in this folder.
   - A window opens and stays open (that IS the server; closing it stops
     ChatISA). Look at chatisa.log in this folder if anything seems wrong.
   - On another machine, open https://chatisa.fsb.miamioh.edu and sign in.
   - Health check: https://chatisa.fsb.miamioh.edu/api/health shows "ok".

6. Connect the existing Task Scheduler job. Pick ONE of these two.

   6a. IF YOU CAN EDIT THE TASK:
   - Open Task Scheduler, find the task that ran the old chatisa.bat,
     edit its Action so "Program/script" is the FULL PATH to
     chatisa-app\\chatisa.bat, and set "Start in" to the chatisa-app folder.
   - Nothing else about the task needs to change.

   6b. IF THE TASK'S PATH IS LOCKED (you lack permission to change it):
   The task points at a fixed path such as
       C:\\Users\\webapp\\.conda\\chat_isa\\chatisa.bat
   which is one level ABOVE the chatisa-app folder. That works: COPY
   chatisa.bat out of chatisa-app up into that parent folder, so you have
       C:\\Users\\webapp\\.conda\\chat_isa\\chatisa.bat        <- the copy the task runs
       C:\\Users\\webapp\\.conda\\chat_isa\\chatisa-app\\...    <- everything else
   The bat looks for the app beside itself first, then in a chatisa-app
   subfolder, so the same file works from either place. Copy it, do not move
   it: leaving the original inside chatisa-app keeps step 5 working and gives
   you a clean copy after every update.

   WATCH OUT, the usual mistake: chatisa.env and chatisa.log stay INSIDE
   chatisa-app, next to chatisa-server.mjs. Do NOT move or copy chatisa.env up
   beside the bat; the server reads it from its own folder and will report it
   missing. Only chatisa.bat is duplicated.

   If the app cannot be found, the bat exits immediately instead of retrying
   in a loop, prints why, and appends a line to chatisa-launcher-error.log
   beside itself. An empty or absent launcher-error log means the path was fine.

   - For either route: close the window from step 5 first, then right-click
     the task > Run, and repeat the checks from step 5.

UPDATING TO A NEW VERSION LATER
-------------------------------
1. On the dev machine:  node scripts/make-deploy-bundle.mjs
2. On the server: end the task (Task Scheduler > End), keep your chatisa.env
3. Replace the chatisa-app folder with the new one, put chatisa.env back in
4. If you used route 6b, also re-copy chatisa.bat from the new chatisa-app up
   into the parent folder, overwriting the old copy. It rarely changes, but a
   stale copy is the kind of thing that wastes an afternoon.
5. Task Scheduler > Run, then re-check /api/health

TROUBLESHOOTING
---------------
- The task "runs" but ChatISA never comes up, and there is no chatisa.log:
  the bat could not find the app. Look for chatisa-launcher-error.log beside
  the bat it ran. Fix: the bat must sit either inside chatisa-app or directly
  beside that folder (step 6b), and the folder must still be named chatisa-app.
- "chatisa.env not found" while the file plainly exists: it is probably beside
  the bat instead of inside chatisa-app. It belongs next to chatisa-server.mjs.
- "cannot listen on port 443": the old app is still running, or the task's
  account lacks permission; run the task as the same account that ran
  Streamlit before.
- "could not read the SSL files": fix the two CHATISA_SSL_* paths in
  chatisa.env to where the .pem and .key actually live.
- Sign-in bounces back to the login page: AUTH_URL must be exactly
  https://chatisa.fsb.miamioh.edu and the Google OAuth client must list the
  redirect URI shown in chatisa.env.example.
- chatisa.log grows over time; delete it whenever it gets large (the server
  recreates it).
- Interview Mentor's voice/microphone does not work, or /api/health?deep=1
  says speech is "broken": open a Command Prompt in chatisa-app and run
      node speech-doctor.mjs
  It tests the network path to Deepgram step by step and prints a verdict
  naming the exact fix (and its output is safe to paste into an IT ticket).
  One known trap it calls out: an inline # comment on the DEEPGRAM_TOKEN
  line in chatisa.env. Keep that line as only  DEEPGRAM_TOKEN=<the key>.
`,
);

let total = 0;
async function size(dir) {
  for (const entry of await readdir(dir, { withFileTypes: true })) {
    const p = join(dir, entry.name);
    if (entry.isDirectory()) await size(p);
    else total += (await stat(p)).size;
  }
}
await size(bundle);

// One zip is what actually travels to the server: a single file transfers
// atomically, where a raw folder of ~50k small files dragged over Remote
// Desktop can silently lose pieces (it did, on 2026-07-25). Windows 10+
// ships bsdtar, which writes zip format when the name ends in .zip.
console.log("Zipping (this takes a minute)...");
const zipPath = join(web, "deploy", "chatisa-app.zip");
await rm(zipPath, { force: true });
const zip = spawnSync(
  "tar",
  ["-a", "-c", "-f", "chatisa-app.zip", "chatisa-app"],
  { cwd: join(web, "deploy"), stdio: "inherit" },
);
if (zip.status !== 0) {
  console.error("Zip failed; the raw folder is still usable, but transfer the");
  console.error("ZIP to servers whenever possible.");
}

console.log(`\nBundle ready: ${bundle}`);
console.log(`Size: ${(total / 1024 / 1024).toFixed(0)} MB (folder)`);
if (existsSync(zipPath)) {
  console.log(`COPY THIS to the server: ${zipPath}`);
  console.log(`  (${((await stat(zipPath)).size / 1024 / 1024).toFixed(0)} MB; extract there, then read INSTALL.txt)`);
}
